/**
 * GET /api/v1/imports/templates/[dataset] — downloadable CSV import
 * templates (Prompt 31 §119/§120/§211/§212/§213).
 *
 * Stable English machine headers + ONE harmless synthetic example row
 * ("Example …"). No real customer data ever appears in a template (§212).
 * The template generated by the app is always accepted by the importer
 * (§213 — the harness verifies this round-trip).
 */
import { NextRequest } from "next/server";
import { getServerSession } from "next-auth";
import { ApiError, route } from "@/lib/api-helpers";
import { NextResponse } from "next/server";
import { authOptions } from "@/lib/auth";
import { assertFreshSession } from "@/lib/auth-security";
import { toCsv } from "@/lib/csv";
import { IMPORT_CATALOG, IMPORT_TEMPLATE_VERSION, templateExampleRow, templateHeaders, type ImportDatasetKey } from "@/lib/data-portability/import-catalog";

export const dynamic = "force-dynamic";

export const GET = route(async (req: NextRequest, params: { params: Promise<{ dataset: string }> }) => {
  // §299 — authentication required, but templates are generic: NO business
  // context is needed, so this route uses the account-scoped gate (a member
  // without an active business can still download templates).
  const session = await getServerSession(authOptions);
  await assertFreshSession(session);
  const { dataset } = await params.params;
  if (!(dataset in IMPORT_CATALOG)) {
    throw new ApiError(404, "IMPORT_NOT_FOUND", "Unknown template dataset.");
  }
  const key = dataset as ImportDatasetKey;
  const meta = IMPORT_CATALOG[key];
  // The template carries its version as the first comment-style column?
  // NO — CSV has no comments; the version is exposed via a response header
  // and documented (§121 — machine headers stay stable).
  const csv = toCsv(templateHeaders(key), [templateExampleRow(key)]);
  const fileResponse = new NextResponse(csv, {
    status: 200,
    headers: {
      "content-type": "text/csv; charset=utf-8",
      "content-disposition": `attachment; filename="${meta.templateFile}"`,
      "cache-control": "private, no-store",
      "x-content-type-options": "nosniff",
      "x-import-template-version": String(IMPORT_TEMPLATE_VERSION),
    },
  });
  return fileResponse;
});
